/* Shared saved-transaction chart, with equivalent previous-period comparison. */
let chartSequence=0;
let chartObserver=null;
const localISO=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function reportRange(mode=financePeriod,now=new Date()){
 if(mode==='Month')return cycleRange(now);
 const start=new Date(now.getFullYear(),mode==='Year'?0:mode==='Quarter'?Math.floor(now.getMonth()/3)*3:now.getMonth(),1),end=localISO(now);
 const length=mode==='Year'?12:mode==='Quarter'?3:1,previous=new Date(start);previous.setMonth(previous.getMonth()-length);
 const elapsed=Math.round((Date.UTC(now.getFullYear(),now.getMonth(),now.getDate())-Date.UTC(start.getFullYear(),start.getMonth(),start.getDate()))/86400000),priorEnd=new Date(previous);priorEnd.setDate(priorEnd.getDate()+elapsed);const priorLimit=new Date(start);priorLimit.setDate(priorLimit.getDate()-1);if(priorEnd>priorLimit)priorEnd.setTime(priorLimit.getTime());
 return {start:localISO(start),end,previousStart:localISO(previous),previousEnd:localISO(priorEnd),mode};
}
function rangeTotals(start,end){const rows=db.transactions.filter(t=>t.date>=start&&t.date<=end);const sum=type=>rows.filter(t=>t.type===type).reduce((s,t)=>s+Number(t.amount),0);return{revenue:sum('Income'),expenses:sum('Expense'),count:rows.length};}
function chartBuckets(mode=financePeriod,now=new Date()){
 const r=reportRange(mode,now),start=new Date(r.start+'T12:00:00'),n=mode==='Month'?Math.round((Date.UTC(now.getFullYear(),now.getMonth(),now.getDate())-Date.UTC(start.getFullYear(),start.getMonth(),start.getDate()))/86400000)+1:mode==='Quarter'?now.getMonth()-start.getMonth()+1:now.getMonth()+1;
 return Array.from({length:n},(_,i)=>{const d=new Date(start);mode==='Month'?d.setDate(d.getDate()+i):d.setMonth(d.getMonth()+i);const from=localISO(d),end=mode==='Month'?from:(()=>{const last=new Date(d.getFullYear(),d.getMonth()+1,0);return localISO(last)<r.end?localISO(last):r.end})(),v=rangeTotals(from,end);return{key:from,label:mode==='Month'?d.toLocaleDateString('en-US',{month:'short',day:'numeric'}):d.toLocaleDateString('en-US',{month:'short'}),period:mode==='Month'?date(from):d.toLocaleDateString('en-US',{month:'long',year:'numeric'}),...v,net:v.revenue-v.expenses};});
}
function rangeControl(){return `<div class="range-switch" role="group" aria-label="Reporting range">${['Month','Quarter','Year'].map(v=>`<button data-range="${v}" aria-pressed="${financePeriod===v}" class="${financePeriod===v?'selected':''}">${v==='Month'?'Monthly cycle':v}</button>`).join('')}</div>`;}
function chart(){
 const uid='cashflow-'+(++chartSequence),r=reportRange(),b=chartBuckets(),tot=rangeTotals(r.start,r.end),prev=rangeTotals(r.previousStart,r.previousEnd),low=Math.min(0,...b.map(v=>v.net)),high=Math.max(1,...b.flatMap(v=>[v.revenue,v.expenses]))*1.15,span=high-low;
 const y=v=>210-(v-low)/span*178,step=600/b.length,x=i=>64+step*(i+.5),width=Math.min(28,step*.26),base=y(0),compact=v=>new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(v);
 const comparison=!prev.count||!prev.revenue?'No prior-period data':`${((tot.revenue-prev.revenue)/prev.revenue*100).toFixed(1)}% revenue vs ${date(r.previousStart)}–${date(r.previousEnd)}`;
 return `<div class="cashflow-chart" data-chart><div class="chart-summary"><span>Revenue <b>${money(tot.revenue)}</b></span><span>Expenses <b>${money(tot.expenses)}</b></span><span>Net <b>${money(tot.revenue-tot.expenses)}</b></span></div><p class="section-note">${date(r.start)}–${date(r.end)} · ${financePeriod==='Month'?(cycleDay()===1?'Current month to date':'Reporting cycle to date'):financePeriod.toLowerCase()+' to date'}<br>${comparison}</p><div class="legend"><span><i class="dot"></i>Revenue</span><span><i class="dot hatched"></i>Expenses</span><span>— Net profit</span></div>${!tot.count?'<p class="section-note">No recorded transactions in this range. Empty buckets do not indicate verified zero activity.</p>':''}<div class="chart-container"><svg class="chart detailed-chart" viewBox="0 0 700 250" role="group" aria-labelledby="${uid}-desc"><title id="${uid}-desc">Saved revenue, expenses and net profit in ${esc(db.settings.currency)}. ${date(r.start)} to ${date(r.end)}. Select any bucket for exact values. Net profit is plotted below zero when negative.</title><defs><pattern id="${uid}-hatch" width="5" height="5" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><rect width="5" height="5" fill="#edeef0"/><line x1="0" y1="0" x2="0" y2="5" stroke="#848a91" stroke-width="1.5"/></pattern></defs>${[0,1,2,3,4].map(i=>{const v=low+span*i/4;return `<line class="gridline" x1="60" x2="670" y1="${y(v)}" y2="${y(v)}"/><text x="53" y="${y(v)+4}" text-anchor="end">${compact(v)}</text>`}).join('')}<line class="zero-line" x1="60" x2="670" y1="${base}" y2="${base}"/>${b.map((v,i)=>`<g class="chart-bucket" tabindex="0" role="button" aria-label="${esc(v.period)}: Revenue ${money(v.revenue)}, expenses ${money(v.expenses)}, net ${money(v.net)}. ${v.count?'Recorded transactions':'No records'}" data-chart-index="${i}"><rect class="chart-hit" x="${x(i)-step/2}" y="20" width="${step}" height="200" fill="transparent"/><rect class="revenue-bar" data-value-key="${v.key}-r" x="${x(i)-width-1}" y="${y(v.revenue)}" width="${width}" height="${Math.max(0,base-y(v.revenue))}" rx="5" fill="var(--accent)"/><rect data-value-key="${v.key}-e" x="${x(i)+2}" y="${y(v.expenses)}" width="${width}" height="${Math.max(0,base-y(v.expenses))}" rx="4" fill="url(#${uid}-hatch)" stroke="#92979e" stroke-width=".5"/><text x="${x(i)}" y="239" text-anchor="middle">${v.label}</text></g>`).join('')}<polyline data-net points="${b.map((v,i)=>`${x(i)},${y(v.net)}`).join(' ')}" fill="none" stroke="#272a2e" stroke-width="2" pointer-events="none"/>${b.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v.net)}" r="3" fill="#272a2e" pointer-events="none"/>`).join('')}</svg><div class="chart-tooltip" role="status" hidden></div></div><div class="chart-foot"><span>${esc(db.settings.currency)} · All buckets use saved records.</span><details><summary>View exact figures</summary><div class="table-wrap"><table><thead><tr><th>Period</th><th>Revenue</th><th>Expenses</th><th>Net</th><th>Records</th></tr></thead><tbody>${b.map(v=>`<tr><td>${v.period}</td><td>${money(v.revenue)}</td><td>${money(v.expenses)}</td><td>${money(v.net)}</td><td>${v.count||'No records'}</td></tr>`).join('')}</tbody></table></div></details></div></div>`;
}
function bindChartDetails(){
 chartObserver?.disconnect();
 if(typeof ResizeObserver!=='undefined'){
  chartObserver=new ResizeObserver(entries=>entries.forEach(({target,contentRect})=>{const width=Math.max(240,contentRect.width),font=Math.max(12,12*700/width);target.querySelectorAll('text').forEach(t=>t.style.fontSize=font+'px');const labels=[...target.querySelectorAll('[data-chart-index] text')],interval=Math.max(1,Math.ceil(labels.length/(width/65)));labels.forEach((t,i)=>t.style.visibility=i%interval===0||i===labels.length-1?'visible':'hidden');}));
  $$('[data-chart] .chart-container').forEach(el=>chartObserver.observe(el));
 }
 $$('[data-chart]').forEach(container=>{const tip=container.querySelector('.chart-tooltip'),b=chartBuckets(),nodes=[...container.querySelectorAll('[data-chart-index]')];const show=node=>{const v=b[Number(node.dataset.chartIndex)];tip.hidden=false;tip.innerHTML=`<b>${esc(v.period)}</b><span>Revenue ${money(v.revenue)}</span><span>Expenses ${money(v.expenses)}</span><span>Net ${money(v.net)}</span><small>${v.count?`${v.count} transactions`:'No records'}</small>`;nodes.forEach(n=>n.classList.toggle('selected',n===node));window.studioMotion?.enter(tip,db.settings.motion,.09);};nodes.forEach((node,i)=>{node.onpointerenter=()=>show(node);node.onfocus=()=>show(node);node.onclick=()=>show(node);node.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();show(node)}if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();nodes[(i+(e.key==='ArrowLeft'?-1:1)+nodes.length)%nodes.length].focus()}if(e.key==='Escape'){tip.hidden=true;node.blur()}};});container.onpointerleave=()=>{if(!container.contains(document.activeElement))tip.hidden=true};container.onfocusout=e=>{if(!container.contains(e.relatedTarget))tip.hidden=true};});
}
function captureCharts(){return $$('[data-chart]').map(c=>({rects:[...c.querySelectorAll('[data-value-key]')].map(el=>({key:el.dataset.valueKey,y:el.getAttribute('y'),height:el.getAttribute('height')}))}));}
function animateCharts(previous){if(!window.studioMotion||!window.studioMotion.full(db.settings.motion))return;$$('[data-chart]').forEach((c,i)=>{c.querySelectorAll('[data-value-key]').forEach(el=>{const old=previous[i]?.rects.find(v=>v.key===el.dataset.valueKey);if(old){const oldY=+old.y,newY=+el.getAttribute('y'),oldH=+old.height,newH=+el.getAttribute('height');if(newH>0)window.studioMotion.run(el,{transform:[`translateY(${oldY-newY}px) scaleY(${oldH/newH})`,'none']},.3,db.settings.motion);}});});}
